P={}; U={}
for row in D.split(';'):
    f=row.split(','); rn=int(f[0]); yr=int(f[1])
    P.setdefault(rn,{})[yr]=[float(x) for x in f[3:8]]
    U.setdefault(rn,{})[yr]=[float(x) for x in f[8:13]]
K=[4,5,6,7,8]; MES={1:'Febrero',2:'Mayo',3:'Agosto',4:'Noviembre'}
Y=list(range(2007,2024))
def geo(x):
    p=1.0
    for v in x: p*=(1+v)
    return p**(1/len(x))-1
def ann(r,k): return (1+r)**(4/k)-1

print("=== REJILLA: MES DE ENTRADA x HORIZONTE ===")
print("Rentabilidad ANUALIZADA de la cartera (media geometrica 2007-2023)\n")
print(f"{'Entrada':<11}" + "".join(f"{k*3:>4}m" for k in K))
CA={}
for rn in [1,2,3,4]:
    fila=[]
    for k in K:
        a=[ann(P[rn][y][K.index(k)],k) for y in Y]; CA[(rn,k)]=geo(a); fila.append(geo(a))
    print(f"{MES[rn]:<11}" + "".join(f"{v*100:>7.2f}%"[:5]+"%" for v in fila))
a4c={}
for k in K:
    a=[st.mean([ann(P[rn][y][K.index(k)],k) for rn in [1,2,3,4]]) for y in Y]
    a4c[k]=geo(a)
print(f"{'4 TRAMOS':<11}" + "".join(f"{a4c[k]*100:>7.2f}%"[:5]+"%" for k in K))

print("\nVENTAJA ANUALIZADA sobre el universo elegible (misma ventana, mismo calculo)\n")
print(f"{'Entrada':<11}" + "".join(f"{k*3:>4}m" for k in K))
EX={}
for rn in [1,2,3,4]:
    fila=[]
    for k in K:
        i=K.index(k)
        a=geo([ann(P[rn][y][i],k) for y in Y]); u=geo([ann(U[rn][y][i],k) for y in Y])
        EX[(rn,k)]=(a-u)*100; fila.append((a-u)*100)
    print(f"{MES[rn]:<11}" + "".join(f"{v:>+7.2f}" for v in fila))
ex4={}
for k in K:
    i=K.index(k)
    a=geo([st.mean([ann(P[rn][y][i],k) for rn in [1,2,3,4]]) for y in Y])
    u=geo([st.mean([ann(U[rn][y][i],k) for rn in [1,2,3,4]]) for y in Y])
    ex4[k]=(a-u)*100
print(f"{'4 TRAMOS':<11}" + "".join(f"{ex4[k]:>+7.2f}" for k in K))
print(f"{'MEDIA 4 MESES':<11}" + "".join(f"{st.mean([EX[(rn,k)] for rn in [1,2,3,4]]):>+7.2f}" for k in K))

print("\n=== ¿QUE APORTA EL AÑO 2? (rendimiento acumulado, sin anualizar) ===")
print(f"{'Entrada':<11}{'12m':>9}{'24m':>9}{'año 2 solo':>12}{'¿aporta?':>10}")
for rn in [1,2,3,4]:
    r12=geo([P[rn][y][0] for y in Y]); r24=geo([P[rn][y][4] for y in Y])
    a2=(1+r24)/(1+r12)-1
    print(f"{MES[rn]:<11}{r12*100:>8.2f}%{r24*100:>8.2f}%{a2*100:>11.2f}%{'SI' if a2>r12 else 'no':>10}")

print("\n=== VOLATILIDAD Y PEOR COHORTE (anualizadas) ===")
print(f"{'Entrada':<11}" + "".join(f"{k*3:>4}m" for k in K))
for rn in [1,2,3,4]:
    print(f"{MES[rn]:<11}" + "".join(f"{min(ann(P[rn][y][K.index(k)],k) for y in Y)*100:>+7.1f}" for k in K))
print("\n(peor cohorte anualizada, en %)")

print("\n\n================ TABLAS DEFINITIVAS ================")
print("\n1) RENTABILIDAD ANUALIZADA DE LA CARTERA (geometrica 2007-2023)\n")
hdr=f"{'Entrada':<12}" + "".join(f"{str(k*3)+'m':>9}" for k in K)
print(hdr); print("-"*len(hdr))
for rn in [1,2,3,4]:
    print(f"{MES[rn]:<12}" + "".join(f"{CA[(rn,k)]*100:>8.2f}%" for k in K))
print(f"{'4 TRAMOS':<12}" + "".join(f"{a4c[k]*100:>8.2f}%" for k in K))

print("\n2) VENTAJA ANUALIZADA SOBRE EL UNIVERSO ELEGIBLE (pp)\n")
print(hdr); print("-"*len(hdr))
for rn in [1,2,3,4]:
    print(f"{MES[rn]:<12}" + "".join(f"{EX[(rn,k)]:>+9.2f}" for k in K))
print(f"{'4 TRAMOS':<12}" + "".join(f"{ex4[k]:>+9.2f}" for k in K))
print(f"{'MEDIA':<12}" + "".join(f"{st.mean([EX[(rn,k)] for rn in [1,2,3,4]]):>+9.2f}" for k in K))

print("\n3) DE DONDE SALE LA VENTAJA (horizonte 12m, entrada febrero)\n")
uni12=geo([U[1][y][0] for y in Y]); car12=geo([P[1][y][0] for y in Y])
SPY=0.0863
print(f"   S&P 500 (solo precio, 2007-2024)          {SPY*100:>7.2f}%")
print(f"   Universo elegible (300M-5B + perfil)      {uni12*100:>7.2f}%   -> +{(uni12-SPY)*100:.2f} pp por ELEGIR EL ESTANQUE")
print(f"   Cartera (top 20% por momentum)            {car12*100:>7.2f}%   -> +{(car12-uni12)*100:.2f} pp por SELECCIONAR DENTRO")
print(f"   {'':<42}{'':>7}      = {(car12-SPY)*100:.2f} pp totales")

print("\n4) DECAIMIENTO DE LA VENTAJA CON EL HORIZONTE\n")
med=[st.mean([EX[(rn,k)] for rn in [1,2,3,4]]) for k in K]
for k,v in zip(K,med): print(f"   {k*3:>2}m : {v:+.2f} pp")
print(f"\n   Caida de 12m a 24m: {med[0]-med[-1]:+.2f} pp ({(med[-1]/med[0]-1)*100:+.0f}%)")
sd=st.stdev([EX[(rn,4)] for rn in [1,2,3,4]])
print(f"   Dispersion entre meses en un mismo horizonte: {sd:.2f} pp")
print("   -> el decaimiento es MENOR que la dispersion entre meses de entrada")
